DO $q$ DECLARE game text; currency text; r jsonb; n integer:=0; before text; BEGIN
SELECT md5(jsonb_agg(s ORDER BY s.id)::text) INTO before FROM table_seats s;
FOREACH currency IN ARRAY ARRAY['chips','diamonds'] LOOP
 UPDATE tournament_participant_funding_receipts SET asset=currency;
 FOREACH game IN ARRAY ARRAY['NLH','SHORT_DECK','FLH','PINEAPPLE','PLO4','PLO5','PLO6','PLO8','FLO8','OFC_PINEAPPLE'] LOOP
 UPDATE tournaments SET game_type=game;
 r:=(SELECT smarter_private.f06_movement_never_dealt_prior('94d9ee21-a872-53ec-bd8c-f23ad8d43378','4bd1908d-72be-5ec7-b59f-72abbe32c589','96fd2136-9f08-548b-8c71-a4df7cb19e67'));
 IF jsonb_array_length(r->'roster')<>2 OR r#>>'{receipts,entries,0,arrival,stack}' IS NULL AND r#>>'{receipts,entries,1,arrival,stack}' IS NULL THEN RAISE EXCEPTION 'ARRIVAL_PROOF_MISSING'; END IF;
 IF (SELECT md5(jsonb_agg(s ORDER BY s.id)::text) FROM table_seats s) IS DISTINCT FROM before THEN RAISE EXCEPTION 'ARRIVAL_CHANGED_SEAT'; END IF;
 n:=n+1;
 END LOOP;
END LOOP;
IF n<>20 THEN RAISE EXCEPTION 'ARRIVAL_MATRIX_INCOMPLETE'; END IF;
END $q$;
